<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Что такое гарантийные обязательства по 44-ФЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Это требования к гарантии качества товара, работы или услуги, к гарантийному сроку и (или) объёму гарантий качества и к гарантийному обслуживанию. Их заказчик устанавливает при необходимости (часть 4 статьи 33). При закупке машин и оборудования такие требования устанавливаются, если предусмотрены технической документацией."}}, {"@type": "Question", "name": "Чем обеспечение гарантийных обязательств отличается от обеспечения исполнения контракта?", "acceptedAnswer": {"@type": "Answer", "text": "Обеспечение исполнения контракта защищает надлежащее исполнение в период действия контракта, а обеспечение гарантийных обязательств — исполнение гарантий после приёмки, в течение гарантийного срока. Это разные суммы, сроки и основания (части 6 и 2.2 статьи 96)."}}, {"@type": "Question", "name": "Какой размер обеспечения гарантийных обязательств?", "acceptedAnswer": {"@type": "Answer", "text": "Размер не может превышать 10% начальной (максимальной) цены контракта, а при закупке у единственного поставщика — 10% цены контракта (часть 2.2 статьи 96). Конкретную величину в пределах 10% заказчик указывает в документации и контракте."}}, {"@type": "Question", "name": "Чем можно обеспечить гарантийные обязательства?", "acceptedAnswer": {"@type": "Answer", "text": "Независимой гарантией по статье 45 44-ФЗ или денежными средствами на указанный заказчиком счёт (часть 3 статьи 96). Способ выбирает исполнитель и вправе изменить его в ходе исполнения."}}, {"@type": "Question", "name": "Какой срок действия должна иметь независимая гарантия?", "acceptedAnswer": {"@type": "Answer", "text": "Срок независимой гарантии должен превышать срок гарантийных обязательств не менее чем на один месяц (часть 3 статьи 96)."}}, {"@type": "Question", "name": "Когда возвращают обеспечение гарантийных обязательств?", "acceptedAnswer": {"@type": "Answer", "text": "Прямого универсального срока 44-ФЗ не устанавливает — его прописывают в контракте. На практике ориентируются на сроки возврата обеспечения по части 27 статьи 34: не более 30 дней с даты исполнения обязательств, а если заказчик установил ограничение по части 3 статьи 30 (закупка среди субъектов малого предпринимательства и социально ориентированных НКО) — не более 15 дней."}}, {"@type": "Question", "name": "Можно ли не предоставлять обеспечение гарантийных обязательств?", "acceptedAnswer": {"@type": "Answer", "text": "Да, в случаях из части 8 статьи 96 (контракт с казённым учреждением, услуга кредита, выдача независимой гарантии БУ/ГУП/МУП). Также возможно освобождение по части 8.1, если участник подтвердит три исполненных без неустоек контракта за три года."}}, {"@type": "Question", "name": "Связаны ли гарантийные обязательства с казначейским сопровождением?", "acceptedAnswer": {"@type": "Answer", "text": "Гарантийные обязательства существуют независимо от казначейского сопровождения. Но при сопровождаемом контракте обеспечение гарантийных обязательств обычно предоставляют независимой гарантией, чтобы не резервировать целевые средства на лицевом счёте на весь гарантийный срок."}}]}
</script>
